css:
.container {
  width: 100%;
  height: 100%;
  /* Add your background pattern here */
  --w: 80px; /* change width according your screen size */
  --bg: black;
  --first: #222;
  --second: #333;

  background:
    radial-gradient(
      circle at right,
      var(--first) 10% 35%,
      var(--second) 30% 36%,
      transparent 30%
    ),
    radial-gradient(
        circle at left,
        var(--first) 15% 35%,
        var(--second) 3% 45%,
        transparent 30%
      )
      var(--bg);
  background-size: var(--w) var(--w);
}
